  let grid_constraint (grid : Fin 5 → Fin 5 → Bool) : Prop := 
    let row_sum (i : Fin 5) := Finset.sum Finset.univ (fun j => 
      if grid i j then (j.val + 1 : ℕ) else 0)
    let col_sum (j : Fin 5) := Finset.sum Finset.univ (fun i => 
      if grid i j then (i.val + 1 : ℕ) else 0)

    (row_sum 0 = 4 ∧ row_sum 1 = 1 ∧ row_sum 2 = 2 ∧ row_sum 3 = 9 ∧ row_sum 4 = 3) ∧

    (col_sum 0 = 2 ∧ col_sum 1 = 3 ∧ col_sum 2 = 5 ∧ col_sum 3 = 5 ∧ col_sum 4 = 4)

  ∃! (count : ℕ), count ∈ ({0, 1} : Set ℕ) ∧
    count = Nat.card {config : (Fin 7 → Bool) × (Fin 5 → Fin 5 → Bool) | 
      self_referential_constraint config.1 ∧ grid_constraint config.2}
